            if success:
                results.append({
                    "endpoint": endpoint,
                    "name": device["name"],
                    "success": True,
                    "message": f"Opened {device['name']} to comfortable position",
                    "position": default_position
                })
            else:
                results.append({
                    "endpoint": endpoint,
                    "success": False,
                    "message": f"Failed to update state for device with endpoint {endpoint}"
                })
        else:
            results.append({
                "endpoint": endpoint,
                "success": False,
